struct cont { int (*k1)(char, void *); int (*k2)(char, char, void *); void *env; };

/* the base case returns the first character's value upward */
static int cont_k1(char a, void *env) { return (int)a; }

static int itoa_cps(int n, struct cont k) {
    if (n < 10) return k.k1((char)('0' + n), k.env);   /* no return value: we call k */
    return itoa_cps(n / 10, (struct cont){ .k2 = k2_helper, .env = k.env });
}
